package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Conjunto de paradas que recorre un domiciliario (tabla RUTA). Se abre con la primera parada y se cierra cuando se
 * vacía.
 * <p>
 * El estado se guarda en español: "ACTIVA" o "CERRADA".
 * <p>
 * EN: Set of stops a courier goes through (RUTA table). It opens with the first stop and closes when it becomes empty.
 * <p>
 * The status is stored in Spanish: "ACTIVA" (active) or "CERRADA" (closed).
 */
@Entity
@Table(name = "RUTA")
public class Route {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del domiciliario. EN: The courier id. */
    @Column(name = "DOMICILIARIO_ID", nullable = false) private Long courierId;
    /** El estado: "ACTIVA" o "CERRADA". EN: The status: "ACTIVA" or "CERRADA". */
    @Column(name = "ESTADO", nullable = false, length = 10) private String status = "ACTIVA";
    /** La hora de inicio en minutos de reloj. EN: The start time in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "INICIO", nullable = false) private Double start;
    /** La hora de cierre en minutos de reloj. EN: The closing time in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FIN") private Double end;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected Route() {}

    /**
     * Abre una ruta para un domiciliario.
     * <p>
     * EN: Opens a route for a courier.
     *
     * @param courierId id del domiciliario / courier id
     * @param start hora de inicio en minutos de reloj / start time in clock minutes
     */
    public Route(long courierId, double start) { this.courierId = courierId; this.start = start; }

    /**
     * Cierra la ruta.
     * <p>
     * EN: Closes the route.
     *
     * @param time hora de cierre en minutos de reloj / closing time in clock minutes
     */
    public void close(double time) { status = "CERRADA"; end = time; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del domiciliario.
     * <p>
     * EN: Returns the courier id.
     *
     * @return el id del domiciliario / the courier id
     */
    public Long getCourierId() { return courierId; }

    /**
     * Devuelve el estado: "ACTIVA" o "CERRADA".
     * <p>
     * EN: Returns the status: "ACTIVA" or "CERRADA".
     *
     * @return el estado: "ACTIVA" o "CERRADA" / the status: "ACTIVA" or "CERRADA"
     */
    public String getStatus() { return status; }

    /**
     * Devuelve la hora de inicio en minutos de reloj.
     * <p>
     * EN: Returns the start time in clock minutes.
     *
     * @return la hora de inicio en minutos de reloj / the start time in clock minutes
     */
    public Double getStart() { return start; }

    /**
     * Devuelve la hora de cierre en minutos de reloj.
     * <p>
     * EN: Returns the closing time in clock minutes.
     *
     * @return la hora de cierre en minutos de reloj / the closing time in clock minutes
     */
    public Double getEnd() { return end; }
}
